(async()=>{try{const m=await apiFetch('/produtos/admin/metrics');const r=m.resumo;const eur=n=>Number(n||0).toLocaleString('pt-PT',{style:'currency',currency:'EUR'});document.getElementById('rp-produtos').textContent=r.total_produtos;document.getElementById('rp-margem').textContent=Number(r.margem_media||0).toFixed(1)+'%';document.getElementById('rp-receita').textContent=eur(r.receita_stock_total);document.getElementById('rp-lucro').textContent=eur(r.lucro_stock_total);document.getElementById('rp-categorias').innerHTML='<tr><th>Categoria</th><th>Produtos</th><th>Margem média</th><th>Lucro potencial stock</th></tr>'+m.categorias.map(c=>`<tr><td>${String(c.categoria??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}</td><td>${c.produtos}</td><td>${Number(c.margem_media||0).toFixed(1)}%</td><td>${eur(c.lucro_stock)}</td></tr>`).join('');}catch(e){document.getElementById('rp-categorias').innerHTML='<tr><td colspan="4" style="color:#B14B33"></td></tr>';document.getElementById('rp-categorias').querySelector('td').textContent='Erro: '+(e.message||'erro desconhecido');}})();
